examples.template:
@OptIn(ExperimentalMonarchApi::class)
MonarchPendingInvitesList(
    invites = invites,
    now = now,
    onResend = {
        // Send the invitation with the id `it` again; throw to show the error.
    },
    onRevoke = { id ->
        invites = invites.filter { it.id != id }
    },
)

